steps.code:
SELECT s.name, c.club
FROM students s
JOIN clubs c ON c.student_id = s.id;

SELECT s.name, c.club
FROM students s
LEFT JOIN clubs c ON c.student_id = s.id;

SELECT city, COUNT(*) AS students, AVG(grade) AS avg_grade
FROM students
GROUP BY city;

SELECT city, AVG(grade) AS avg_grade
FROM students GROUP BY city
HAVING AVG(grade) > 80;

