INSERT INTO orders(customer_id, product_id, qty) VALUES (1,1,1), (1,2,2), (2,3,1), (2,2,1);

-- Revenue per customer
SELECT c.name, SUM(p.price * o.qty) AS spent
FROM orders o
JOIN customers c ON c.id = o.customer_id
JOIN products p ON p.id = o.product_id
GROUP BY c.name
ORDER BY spent DESC;
